def main(args: dict) -> dict:
    import json
    import re
    raw = args.get('query', '')
    try:
        if isinstance(raw, str):
            raw = raw.strip().lstrip('\ufeff')
            if raw.startswith('```'):
                raw = re.sub(r'^```[^\n]*\n?', '', raw)
                raw = re.sub(r'\n?```\s*$', '', raw).strip()
        data = json.loads(raw) if isinstance(raw, str) else raw
        if isinstance(data, dict) and 'query' in data and not any(k in data for k in ['需求清单', 'requirements', 'items']):
            data = json.loads(data['query']) if isinstance(data['query'], str) else data['query']
        if isinstance(data, dict):
            data = data.get('需求清单', data.get('requirements', data.get('items')))
        if not isinstance(data, list):
            raise ValueError('输入必须是需求清单JSON数组，或包含“需求清单”数组的对象')
        if len(data) > 1000:
            raise ValueError('单次最多1000条，请分批提交')
        counts = {}
        for item in data:
            key = item.get('需求ID') if isinstance(item, dict) else None
            if isinstance(key, str) and key.strip():
                counts[key.strip()] = counts.get(key.strip(), 0) + 1
        items = []
        for i, item in enumerate(data):
            key = item.get('需求ID') if isinstance(item, dict) else None
            duplicate = isinstance(key, str) and counts.get(key.strip(), 0) > 1
            items.append(json.dumps({'position': i+1, 'data': item, 'duplicate': duplicate}, ensure_ascii=False))
        return {'valid': True, 'items': items, 'error_report': '', 'count': len(items)}
    except (ValueError, TypeError) as exc:
        return {'valid': False, 'items': [], 'error_report': '# 需求清单核查汇总报告\n\n输入异常：' + str(exc), 'count': 0}

def main(args: dict) -> dict:
    import json
    packed = json.loads(args['item'])
    data, position = packed.get('data'), packed.get('position', 0)
    fields = ['需求ID', '需求名称', '需求描述', '提出部门']
    if isinstance(data, dict):
        missing = [k for k in fields if not isinstance(data.get(k), str) or not data[k].strip()]
    else:
        missing = list(fields)
        data = {}
    cleaned = {k: data[k].strip() if isinstance(data.get(k), str) else '' for k in fields}
    result = {'序号': position, '需求ID': cleaned['需求ID'] or '第%d条（ID缺失）' % position,
              '需求名称': cleaned['需求名称'], '提出部门': cleaned['提出部门'], '核验状态': '信息不全',
              '核验说明': '缺少或无效字段：' + '、'.join(missing), '缺失字段': missing,
              '优化建议': ['补充有效的' + k for k in missing]}
    if '需求描述' in missing:
        result['优化建议'].append('需求描述应补充业务价值、使用场景、功能范围和验收要求')
    return {'complete': not missing, 'payload': json.dumps(cleaned, ensure_ascii=False),
            'position': position, 'duplicate': bool(packed.get('duplicate')),
            'incomplete_result': json.dumps(result, ensure_ascii=False)}

def parse_model(raw):
    import json
    import re
    if isinstance(raw, dict):
        return raw
    if not isinstance(raw, str):
        raise ValueError('模型未返回文本或对象')
    raw = re.sub(r'<think>.*?</think>', '', raw, flags=re.S).strip()
    try:
        obj = json.loads(raw)
        if isinstance(obj, dict):
            return obj
    except (ValueError, TypeError):
        pass
    match = re.search(r'```(?:json)?\s*(.*?)```', raw, re.S)
    if match:
        obj = json.loads(match.group(1))
        if isinstance(obj, dict):
            return obj
    pos = raw.find('{')
    if pos >= 0:
        obj, _ = json.JSONDecoder().raw_decode(raw[pos:])
        if isinstance(obj, dict):
            return obj
    raise ValueError('模型输出不是有效JSON对象')

def main(args: dict) -> dict:
    import json
    payload = json.loads(args['payload'])
    try:
        obj = parse_model(args.get('raw_output'))
        status, note, suggestions = obj.get('核验状态'), obj.get('核验说明'), obj.get('优化建议')
        if status not in ['核验通过', '待优化'] or not isinstance(note, str) or not note.strip():
            raise ValueError('核验状态或说明不符合约定')
        if not isinstance(suggestions, list) or any(not isinstance(s, str) or not s.strip() for s in suggestions):
            raise ValueError('优化建议格式错误')
        if status == '待优化' and not suggestions:
            suggestions = ['根据核验说明完善业务场景、功能范围及验收要求']
        if status == '核验通过' and suggestions:
            status = '待优化'
    except (ValueError, TypeError, KeyError):
        status, note, suggestions = '待优化', '模型结果格式异常，本条未判通过，需要重新核查或人工复核', ['重新运行本条核查或人工复核，不能据此视为已通过']
    if args.get('duplicate'):
        status = '待优化'
        note += '；需求ID在本清单内重复'
        suggestions.append('修改重复需求ID，确保清单内唯一')
    result = {'序号': args['position'], '需求ID': payload['需求ID'], '需求名称': payload['需求名称'],
              '提出部门': payload['提出部门'], '核验状态': status, '核验说明': note,
              '缺失字段': [], '优化建议': list(dict.fromkeys(suggestions))}
    return {'result': json.dumps(result, ensure_ascii=False)}

def main(args: dict) -> dict:
    import json
    original = args.get('items') or []
    results = args.get('review_results') or []
    by_position = {}
    for raw in results:
        try:
            obj = json.loads(raw) if isinstance(raw, str) else raw
            if isinstance(obj, dict) and isinstance(obj.get('序号'), int):
                by_position[obj['序号']] = obj
        except (ValueError, TypeError):
            pass
    details = []
    for i, packed in enumerate(original):
        position = i+1
        if position in by_position:
            details.append(by_position[position])
        else:
            data = json.loads(packed).get('data')
            data = data if isinstance(data, dict) else {}
            details.append({'序号': position, '需求ID': data.get('需求ID') or '第%d条' % position,
                '需求名称': data.get('需求名称', ''), '提出部门': data.get('提出部门', ''),
                '核验状态': '待优化', '核验说明': '本条未返回有效核查结果，需重新运行或人工复核',
                '缺失字段': [], '优化建议': ['重新核查本条，避免遗漏']})
    passed = sum(d.get('核验状态') == '核验通过' for d in details)
    incomplete = sum(d.get('核验状态') == '信息不全' for d in details)
    pending = len(details)-passed-incomplete
    lines = ['# 需求清单核查汇总报告', '', '1. 统计汇总',
             '总条目%d条，合规%d条，待优化%d条，信息不全%d条。' % (len(details), passed, pending, incomplete), '', '2. 逐条详情']
    for d in details:
        label = str(d.get('需求ID', '')).replace('\n', ' ')
        lines.append('%s：%s，%s。' % (label, d.get('核验状态', ''), d.get('核验说明', '').rstrip('。')))
        for s in d.get('优化建议', []):
            lines.append('  - ' + s)
    lines.extend(['', '3. 整体优化汇总意见'])
    if not details:
        advice = '需求清单为空，未执行条目核查，请提交至少一条业务需求。'
    elif passed == len(details):
        advice = '全部需求核验通过。字段完整、描述符合本作业基础编写规范，可进入后续评审。'
    elif pending == 0:
        advice = '请先补齐信息不全条目的缺失字段，需求描述需写明业务价值和使用场景，补充后重新核查。'
    else:
        advice = '请依据逐条核验结果完善需求，补充缺失内容后重新核查。'
    base = '\n'.join(lines)
    payload = {'统计数据': {'总条目': len(details), '合规': passed, '待优化': pending, '信息不全': incomplete}, '逐条详情': details}
    return {'need_advice': pending > 0, 'base_report': base,
            'report': base + '\n' + advice, 'summary_payload': json.dumps(payload, ensure_ascii=False),
            'passed': passed, 'pending': pending, 'incomplete': incomplete, 'total': len(details)}

def main(args: dict) -> dict:
    advice = args.get('advice')
    if not isinstance(advice, str) or not advice.strip():
        advice = '汇总意见未生成成功，请依据上方逐条核验详情补充材料、明确范围后重新核查。'
    return {'report': args['base_report'] + '\n' + advice.strip()}
